// 영수증에 손으로 쓴 숫자를 읽는다 — **기기 안에서.**
//
// 2026-10-05 사장님: "영수증을 올리면 가격 품목 어디서 언제 샀는지를 내가 직접
// 타자로 쳐서 하나하나 입력하는 게 아니라 적용되도록." AI 없이 간다는 결정도
// 같은 날 하셨다("그대로 가"). 사진은 기기 밖으로 나가지 않는다.
//
// ── 왜 급여 카드의 판별기를 그냥 쓰지 않는가
//
// timecard-handdigits.js 는 MNIST(서양 손글씨)로 배운 망이다. 급여 카드
// 머리의 「115 年 9 月份」은 32/32 로 읽었는데, 영수증 숫자는 **66%** 밖에
// 못 읽었다. 업체 분들이 쓰는 숫자는 모양이 다르다 — 0 을 길게 눌러 쓰고,
// 1 에 갈고리가 없고, 5 의 위 획이 떨어져 있다.
//
// ── 그래서 영수증 글씨로 견본을 만들었다
//
// 사장님 엑셀 장부가 **정답표**다. 종이에서 센 줄 수가 엑셀 줄 수와 맞은
// 영수증은 「종이 n째 줄 = 엑셀 n째 줄」이므로, 단가·금액 칸의 글자 수가
// 엑셀 자리 수와 같으면 글자마다 정답을 붙일 수 있다. 房信菓菜行 사진
// 120장에서 그렇게 1,165자를 모았다(사람이 하나도 안 적었다).
//
// 가까운 이웃 세 개로 읽는다. 재본 것(사진을 다섯 묶음으로 나눠 돌려가며):
//
//   MNIST 망            66.0%
//   숫자마다 평균 한 장  73.9%
//   가까운 이웃 세 개    88.4%
//
// 1,165자를 다 담으면 파일이 커서, 숫자마다 k-means 로 40개씩 줄였다
// (87.1% — 1.3% 를 38KB 와 바꿨다).
//
// ── 못 읽는 것은 못 읽는다고 한다
//
// 숫자 하나가 88% 면 세 자리 금액은 68% 다. 그래서 이 파일은 **확신(p)을
// 같이** 돌려주고, 부르는 쪽이 수량 × 단가 = 금액 과 인쇄된 合計 로 한 번 더
// 본다. 틀린 값을 표시 없이 채우는 것이 제일 나쁘다.
//
// 입력은 timecard-handdigits.js 와 같다 — 28×28 Float32, 0 바탕 1 잉크,
// 무게중심이 가운데(receipt-ocr.js 의 toGlyphImage 가 만든다).
(function (root) {
  "use strict";

  // 견본 400개. 14×14 를 0~15 로 눌러 4비트씩 담았다.
  const LABELS = "";
  const DATA = "";

  const DIM = 196;          // 14×14
  const PACKED = 98;        // 4비트 두 개씩

  let protos = null;        // [{d, f:Float32Array(196)}] — 길이 1로 맞춘 것

  function unpack() {
    if (protos) return protos;
    const bin = typeof atob === "function"
      ? atob(DATA)
      : Buffer.from(DATA, "base64").toString("binary");
    protos = [];
    for (let i = 0; i < LABELS.length; i++) {
      const f = new Float32Array(DIM);
      let m = 0;
      for (let j = 0; j < PACKED; j++) {
        const byte = bin.charCodeAt(i * PACKED + j);
        const a = (byte >> 4) & 15, b = byte & 15;
        f[j * 2] = a; f[j * 2 + 1] = b;
        m += a * a + b * b;
      }
      m = Math.sqrt(m) || 1;
      for (let j = 0; j < DIM; j++) f[j] /= m;
      protos.push({ d: +LABELS[i], f });
    }
    return protos;
  }

  /**
   * 28×28 을 견줄 모양으로 바꾼다.
   *
   * 한 점 흐리게 한 뒤 14×14 로 줄인다. 손글씨는 획 굵기와 한두 점 밀림이
   * 늘 다른데, 흐리게 해 두면 그것에 덜 흔들린다(28×28 그대로 88.4%,
   * 흐려서 14×14 로 줄이면 88.8% — 작아지면서 오히려 조금 나아졌다).
   */
  function featureOf(img) {
    const blurred = new Float32Array(784);
    for (let y = 0; y < 28; y++) {
      for (let x = 0; x < 28; x++) {
        let s = 0, n = 0;
        for (let dy = -1; dy <= 1; dy++) {
          const yy = y + dy;
          if (yy < 0 || yy >= 28) continue;
          for (let dx = -1; dx <= 1; dx++) {
            const xx = x + dx;
            if (xx < 0 || xx >= 28) continue;
            s += img[yy * 28 + xx]; n++;
          }
        }
        blurred[y * 28 + x] = n ? s / n : 0;
      }
    }
    const f = new Float32Array(DIM);
    let m = 0;
    for (let y = 0; y < 14; y++) {
      for (let x = 0; x < 14; x++) {
        const v = (blurred[y * 2 * 28 + x * 2] + blurred[y * 2 * 28 + x * 2 + 1]
          + blurred[(y * 2 + 1) * 28 + x * 2] + blurred[(y * 2 + 1) * 28 + x * 2 + 1]) / 4;
        // 견본과 같은 눈금(0~15)으로 맞춘다
        const q = Math.round(Math.max(0, Math.min(1, v)) * 15);
        f[y * 14 + x] = q; m += q * q;
      }
    }
    m = Math.sqrt(m) || 1;
    for (let j = 0; j < DIM; j++) f[j] /= m;
    return f;
  }

  const NEIGHBOURS = 3;

  /**
   * 숫자 하나를 읽는다.
   * @param img 28×28 Float32 (0 바탕, 1 잉크, 무게중심 가운데)
   * @returns {digit, p, probs} — p 는 **이 숫자일 확신**. 1 에 가까우면
   *   가까운 이웃 세 개가 입을 모은 것이고, 0.4 쯤이면 둘로 갈린 것이다.
   */
  function classify(img) {
    if (!img || img.length !== 784) return null;
    const ps = unpack();
    const f = featureOf(img);
    // 가까운 세 개
    const best = [];
    for (const p of ps) {
      let v = 0;
      for (let j = 0; j < DIM; j++) v += f[j] * p.f[j];
      if (best.length < NEIGHBOURS) { best.push({ v, d: p.d }); best.sort((a, b) => a.v - b.v); }
      else if (v > best[0].v) { best[0] = { v, d: p.d }; best.sort((a, b) => a.v - b.v); }
    }
    // 닮은 만큼을 표로 센다. 안 닮은 이웃이 표를 많이 쥐지 않게 **가장
    // 가까운 것을 기준으로** 깎는다 — 그래야 「셋 다 비슷하게 멀다」가
    // 낮은 확신으로 나온다.
    const top = best[best.length - 1].v;
    const probs = new Array(10).fill(0);
    let sum = 0;
    for (const b of best) {
      const wgt = Math.max(0, b.v - (top - 0.15)) / 0.15;
      probs[b.d] += wgt; sum += wgt;
    }
    if (!sum) { probs[best[best.length - 1].d] = 1; sum = 1; }
    for (let d = 0; d < 10; d++) probs[d] /= sum;
    let digit = 0;
    for (let d = 1; d < 10; d++) if (probs[d] > probs[digit]) digit = d;
    return { digit, p: probs[digit], probs, score: top };
  }

  const api = { classify, featureOf, count: LABELS.length };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.HG_RECEIPT_DIGITS = api;
})(typeof window !== "undefined" ? window : globalThis);
